text(await tools.exec_command({cmd:`cat > /app/index.html <<'EOF'
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<meta name="color-scheme" content="dark">
<title>Vegan ramen</title>
<style>
  * { box-sizing: border-box; }
  html, body { width: 100%; height: 100%; margin: 0; overflow: hidden; background: #100e0e; }
  canvas { display: block; width: 100%; height: 100%; }
</style>
</head>
<body>
<canvas id="scene" role="img" aria-label="Steam rises from a dark ceramic bowl of golden ramen with seared tofu, shiitake, bok choy, and nori."></canvas>
<script>
(() => {
  'use strict';

  const canvas = document.getElementById('scene');
  const screen = canvas.getContext('2d', { alpha: false });
  const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)');
  const tau = Math.PI * 2;
  const mix = (a, b, t) => a + (b - a) * t;
  const clamp = (x, low = 0, high = 1) => Math.max(low, Math.min(high, x));
  const smooth = x => {
    const t = clamp(x);
    return t * t * (3 - 2 * t);
  };

  let seed = 72436;
  function random() {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    return seed / 4294967296;
  }
  const between = (a, b) => mix(a, b, random());
  const choose = values => values[Math.floor(random() * values.length)];

  function layer(width, height) {
    const surface = document.createElement('canvas');
    surface.width = width;
    surface.height = height;
    return surface;
  }

  function linear(ctx, x, y, x1, y1, stops) {
    const gradient = ctx.createLinearGradient(x, y, x1, y1);
    stops.forEach(([at, color]) => gradient.addColorStop(at, color));
    return gradient;
  }

  function oval(ctx, x, y, rx, ry, fill, rotation = 0) {
    ctx.beginPath();
    ctx.ellipse(x, y, rx, ry, rotation, 0, tau);
    ctx.fillStyle = fill;
    ctx.fill();
  }

  function glow(ctx, x, y, rx, ry, stops) {
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(rx, ry);
    const gradient = ctx.createRadialGradient(0, 0, 0, 0, 0, 1);
    stops.forEach(([at, color]) => gradient.addColorStop(at, color));
    ctx.fillStyle = gradient;
    ctx.fillRect(-1, -1, 2, 2);
    ctx.restore();
  }

  function curve(ctx, data, color, width) {
    ctx.beginPath();
    ctx.moveTo(data[0], data[1]);
    ctx.bezierCurveTo(...data.slice(2));
    ctx.lineWidth = width;
    ctx.strokeStyle = color;
    ctx.stroke();
  }

  function trace(ctx, points, closed = false) {
    ctx.beginPath();
    ctx.moveTo(...points[0]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(...points[i]);
    if (closed) ctx.closePath();
  }

  // Generate a fine, repeatable grain for the table and the ceramic glaze.
  const grain = layer(256, 256);
  const grainCtx = grain.getContext('2d');
  const grainPixels = grainCtx.createImageData(grain.width, grain.height);
  for (let i = 0; i < grainPixels.data.length; i += 4) {
    const light = random() < .49;
    const value = light ? 239 : 2;
    grainPixels.data[i] = value;
    grainPixels.data[i + 1] = value;
    grainPixels.data[i + 2] = light ? 229 : 5;
    grainPixels.data[i + 3] = between(4, 69);
  }
  grainCtx.putImageData(grainPixels, 0, 0);

  const backdrop = layer(1, 1);
  let width, height, dpr, scale, originX, originY;
  function paintBackdrop() {
    backdrop.width = canvas.width;
    backdrop.height = canvas.height;
    const ctx = backdrop.getContext('2d', { alpha: false });
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.fillStyle = linear(ctx, 0, 0, 0, height, [
      [0, '#0d0b0c'], [.51, '#161112'], [.74, '#1b1513'], [1, '#0d0d0e']
    ]);
    ctx.fillRect(0, 0, width, height);
    ctx.translate(originX, originY);
    ctx.scale(scale, scale);

    glow(ctx, -175, -149, 655, 487, [
      [0, 'rgba(107,63,38,.61)'], [.38, 'rgba(84,45,30,.47)'],
      [.72, 'rgba(49,27,24,.28)'], [1, 'rgba(34,17,17,0)']
    ]);
    glow(ctx, 326, -130, 495, 377, [
      [0, 'rgba(26,45,43,.32)'], [.62, 'rgba(20,32,34,.13)'], [1, 'rgba(15,22,24,0)']
    ]);

    // A very soft falloff gives the counter depth without a hard horizon.
    ctx.fillStyle = linear(ctx, 0, 38, 0, 355, [
      [0, 'rgba(11,11,13,0)'], [.28, 'rgba(14,13,14,.13)'],
      [.75, 'rgba(17,17,19,.59)'], [1, 'rgba(13,13,15,.83)']
    ]);
    const bounds = [width / (2 * scale) + 4, height / scale];
    ctx.fillRect(-bounds[0], 38, bounds[0] * 2, bounds[1]);
    glow(ctx, -128, 217, 570, 227, [
      [0, 'rgba(137,84,48,.27)'], [.46, 'rgba(94,54,35,.22)'],
      [.75, 'rgba(57,38,29,.12)'], [1, 'rgba(39,25,23,0)']
    ]);
    glow(ctx, 290, 215, 492, 205, [
      [0, 'rgba(55,71,65,.15)'], [.55, 'rgba(33,50,51,.1)'], [1, 'rgba(22,32,37,0)']
    ]);

    seed = 23092;
    ctx.lineCap = 'round';
    for (let i = 0; i < 3100; i++) {
      const y = between(73, Math.min(bounds[1], 570));
      const x = between(-bounds[0], bounds[0]);
      const distance = Math.hypot((x + 120) / 650, (y - 238) / 310);
      const opacity = clamp(1 - distance) * between(.025, .12);
      const length = between(3, 84) * (.55 + (y - 73) / 330);
      const tilt = between(-1.8, 2.4) + x * .009;
      const color = random() < .46 ? '188,139,98' : '4,6,8';
      curve(ctx, [x, y, x + length * .2, y + tilt * .7, x + length * .7, y + tilt * .3, x + length, y + tilt],
        'rgba(' + color + ',' + opacity + ')', between(.25, 1.35));
    }
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.globalAlpha = .32;
    ctx.fillStyle = ctx.createPattern(grain, 'repeat');
    ctx.fillRect(0, 0, width, height);
    ctx.globalAlpha = 1;
  }

  const bowl = layer(1640, 1020);
  const art = bowl.getContext('2d');
  art.scale(2, 2);
  art.translate(410, 235);
  art.lineJoin = 'round';
  art.lineCap = 'round';

  function paintCeramic(ctx) {
    const body = new Path2D('M -368 -2 C -364 66 -331 150 -267 196 C -228 225 -186 239 -137 245 C -63 257 63 257 137 245 C 186 239 228 225 267 196 C 331 150 364 66 368 -2 Z');

    oval(ctx, 1, 230, 158, 28, '#161815');
    oval(ctx, 1, 235, 153, 24, linear(ctx, 0, 217, 0, 259, [
      [0, '#212924'], [.55, '#161d1b'], [.83, '#17201d'], [.94, '#4e3a28'], [1, '#1b140f']
    ]));
    ctx.save();
    ctx.clip(body);
    ctx.fillStyle = linear(ctx, -365, -12, 365, 124, [
      [0, '#171b18'], [.12, '#30382c'], [.25, '#4b5949'], [.42, '#354b43'],
      [.6, '#223a38'], [.78, '#172c30'], [.89, '#16252a'], [1, '#10191d']
    ]);
    ctx.fillRect(-370, -5, 740, 269);
    ctx.fillStyle = linear(ctx, 0, 14, 0, 256, [
      [0, 'rgba(1,6,9,.28)'], [.44, 'rgba(7,15,16,0)'], [.64, 'rgba(10,18,18,.08)'],
      [.82, 'rgba(6,10,12,.53)'], [1, 'rgba(5,8,9,.86)']
    ]);
    ctx.fillRect(-370, -5, 740, 269);
    glow(ctx, -258, 106, 257, 134, [
      [0, 'rgba(214,162,92,.23)'], [.48, 'rgba(174,128,78,.12)'], [1, 'rgba(123,78,42,0)']
    ]);
    glow(ctx, -73, 158, 292, 91, [
      [0, 'rgba(88,135,120,.15)'], [.75, 'rgba(83,130,110,.07)'], [1, 'rgba(94,115,102,0)']
    ]);
    glow(ctx, 263, 97, 149, 128, [
      [0, 'rgba(77,119,139,.1)'], [1, 'rgba(77,119,139,0)']
    ]);

    function shell(angle, depth) {
      const radius = 368 * (1 - .59 * Math.pow(depth, 1.94));
      return [
        Math.cos(angle) * radius,
        217 * depth + Math.sin(angle) * 147 * (1 - .81 * depth)
      ];
    }

    for (let i = 0; i < 134; i++) {
      const angle = (i + between(-.37, .37)) * Math.PI / 134;
      const end = between(.67, 1.01);
      const points = [];
      const bend = between(-.033, .033);
      for (let v = 0; v <= 16; v++) {
        const t = v * end / 16;
        points.push(shell(angle + bend * Math.sin(t * 4), t));
      }
      trace(ctx, points);
      ctx.lineWidth = between(.31, 2.5);
      ctx.strokeStyle = random() < .55 ? 'rgba(3,9,12,.19)' : 'rgba(187,176,132,.085)';
      ctx.stroke();
    }

    for (let i = 0; i < 72; i++) {
      const depth = i / 74;
      const start = between(-.07, .47);
      const end = Math.PI - between(-.07, .4);
      const points = [];
      const wobble = between(.0015, .0070);
      for (let v = 0; v <= 70; v++) {
        const angle = mix(start, end, v / 70);
        points.push(shell(angle, depth + wobble * Math.sin(angle * 11 + i)));
      }
      trace(ctx, points);
      ctx.strokeStyle = random() < .61 ? 'rgba(3,9,10,.21)' : 'rgba(176,164,129,.095)';
      ctx.lineWidth = between(.28, 1.6);
      ctx.stroke();
    }

    for (let i = 0; i < 12900; i++) {
      const x = between(-367, 367);
      const y = between(30, 248);
      const opacity = between(.025, .25) * (1 - y / 379);
      const color = choose(['13,13,12', '11,21,21', '4,10,12', '138,145,119', '175,144,101']);
      oval(ctx, x, y, between(.17, 1.69), between(.15, .89), 'rgba(' + color + ',' + opacity + ')', between(-.5, .5));
    }

    ctx.globalAlpha = .40;
    ctx.fillStyle = ctx.createPattern(grain, 'repeat');
    ctx.fillRect(-370, 0, 740, 261);
    ctx.globalAlpha = 1;
    ctx.restore();

    oval(ctx, 0, 0, 369.5, 149.5, '#191916');
    oval(ctx, 0, -2, 367, 148.4, linear(ctx, -245, -115, 259, 129, [
      [0, '#b48150'], [.18, '#8d603d'], [.33, '#755238'], [.52, '#544436'],
      [.69, '#8d6948'], [.86, '#654738'], [1, '#3d3430']
    ]));
    oval(ctx, 0, -1, 361.5, 142.6, linear(ctx, 0, -138, 0, 144, [
      [0, '#23251d'], [.26, '#28261d'], [.5, '#533c24'],
      [.77, '#8e592f'], [.94, '#594029'], [1, '#242725']
    ]));
    oval(ctx, 0, 4, 348, 132, '#492613');

    for (let i = 0; i < 4200; i++) {
      const a = between(0, tau);
      const inset = between(0, 1);
      const x = Math.cos(a) * mix(365.7, 355, inset);
      const y = Math.sin(a) * mix(146.5, 139, inset) - 2;
      oval(ctx, x, y, between(.18, 1.45), between(.16, .68),
        choose(['#492d2452', '#e4a56b58', '#1c201b81', '#ddaf8d52', '#44352b84']));
    }

    const glazeArcs = [
      [3.24, 4.12, 365, 147, '#e4b17c88', 1.65],
      [3.44, 3.87, 366, 148, '#f8c994aa', .85],
      [2.34, 3.19, 367, 147, '#d49d6e8e', 1.8],
      [2.59, 3.06, 367, 147.5, '#ffd39b93', .8],
      [.33, 1.2, 365, 147, '#b2aa924a', 1.2],
      [.91, 2.47, 368.5, 149.2, '#c585595c', 1.05]
    ];
    for (const [start, end, rx, ry, color, size] of glazeArcs) {
      ctx.beginPath();
      ctx.ellipse(0, -1.5, rx, ry, 0, start, end);
      ctx.lineWidth = size;
      ctx.strokeStyle = color;
      ctx.stroke();
    }
  }

  function brothMask(ctx) {
    ctx.beginPath();
    ctx.ellipse(0, 3.5, 348, 132, 0, 0, tau);
    ctx.clip();
  }

  function paintBroth(ctx) {
    ctx.save();
    brothMask(ctx);
    ctx.fillStyle = linear(ctx, -154, -127, 141, 134, [
      [0, '#744420'], [.23, '#ad692e'], [.4, '#be7c38'],
      [.66, '#965122'], [.87, '#7e3e1b'], [1, '#54321b']
    ]);
    ctx.fillRect(-350, -132, 700, 273);
    glow(ctx, -115, -20, 254, 133, [
      [0, 'rgba(255,188,96,.51)'], [.48, 'rgba(235,149,56,.32)'], [1, 'rgba(226,135,32,0)']
    ]);
    glow(ctx, 210, 42, 182, 101, [
      [0, 'rgba(159,51,13,.32)'], [.63, 'rgba(148,40,16,.2)'], [1, 'rgba(95,25,14,0)']
    ]);
    glow(ctx, 0, 132, 288, 36, [
      [0, 'rgba(64,24,9,.4)'], [1, 'rgba(59,26,12,0)']
    ]);
    for (let i = 0; i < 6600; i++) {
      const x = between(-349, 349);
      const y = between(-130, 135);
      const size = between(.22, 2.1);
      oval(ctx, x, y, size, size * between(.17, .48),
        choose(['#f5c17b25', '#fead412d', '#50250e43', '#68300c56', '#ffda9330', '#ac3a1840']));
    }

    // Chili oil lenses, bright along the edge that catches the light.
    for (let i = 0; i < 700; i++) {
      const x = between(-345, 345);
      const y = between(-127, 135);
      const size = .42 + Math.pow(random(), 3.1) * 7.9;
      const vertical = size * between(.29, .56);
      const spin = between(-.27, .27);
      oval(ctx, x + .4, y + .38, size * 1.1, vertical * 1.14, '#f7b85c48', spin);
      oval(ctx, x, y, size, vertical, choose(['#9239199f', '#ad4a1bb7', '#65300e90', '#d87724c7', '#b85b229b']), spin);
      if (size > 2.0) {
        ctx.beginPath();
        ctx.ellipse(x - .13, y - .07, size * .85, vertical * .91, spin, 3.3, 4.72);
        ctx.strokeStyle = choose(['#ffcf8687', '#ffc46389', '#fca64770']);
        ctx.lineWidth = between(.34, .78);
        ctx.stroke();
      }
    }

    for (let i = 0; i < 95; i++) {
      const x = between(-349, 349);
      const y = between(-124, 128);
      const length = between(3, 38);
      curve(ctx, [x, y, x + length * .28, y - 1.4, x + length * .78, y + 1.9, x + length, y + .4],
        choose(['#ffd3842b', '#fac38538', '#6d2f183e', '#e9943b47']), between(.34, 1));
    }

    ctx.beginPath();
    ctx.ellipse(0, 2, 345, 130, 0, Math.PI + .16, tau - .16);
    ctx.lineWidth = 10;
    ctx.strokeStyle = '#48270f50';
    ctx.stroke();
    ctx.beginPath();
    ctx.ellipse(0, 3, 346, 131, 0, .22, Math.PI - .18);
    ctx.strokeStyle = '#47240f63';
    ctx.lineWidth = 4;
    ctx.stroke();
    ctx.restore();
  }

  function noodleNest(ctx, x, y, rx, ry, count) {
    ctx.save();
    const stack = [];
    for (let i = 0; i < count; i++) {
      const size = between(.23, .93);
      const a = between(0, tau);
      const offset = between(.12, .84) * (1 - size * .63);
      const centerX = x + Math.cos(a) * rx * offset;
      const centerY = y + Math.sin(a) * ry * offset;
      const start = between(-Math.PI, Math.PI);
      const length = between(1.6, 5.2);
      const lean = between(-.32, .32);
      const waves = between(3.2, 7.7);
      const phase = between(0, tau);
      const stride = between(.08, .37);
      const points = [];
      for (let step = 0; step <= 66; step++) {
        const t = step / 66;
        const angle = start + length * t;
        const amp = 1 + stride * Math.sin(angle * waves + phase) +
          .15 * Math.sin(angle * 3 + phase);
        const dx = Math.cos(angle) * rx * size * amp;
        const dy = Math.sin(angle) * ry * size * amp;
        points.push([centerX + dx, centerY + dy + dx * lean * .35]);
      }
      stack.push({ points, size: between(2.6, 5.3), light: random() });
    }

    for (const { points, size, light } of stack) {
      trace(ctx, points.map(([px, py]) => [px + .48, py + 1.6]));
      ctx.lineWidth = size + 2.6;
      ctx.strokeStyle = light < .34 ? '#4e210e9a' : '#6b2c12b4';
      ctx.stroke();
      trace(ctx, points);
      ctx.lineWidth = size + .5;
      ctx.strokeStyle = light < .34 ? '#a96028' : '#b97032';
      ctx.stroke();
      trace(ctx, points.map(([px, py]) => [px - .36, py - .52]));
      ctx.lineWidth = size * .73;
      ctx.strokeStyle = light < .20 ? '#c98842' : light < .58 ? '#e2a24f' : '#edb55f';
      ctx.stroke();
      const start = Math.floor(between(1, 20));
      const end = Math.floor(between(42, 65));
      trace(ctx, points.slice(start, end).map(([px, py]) => [px - .48, py - size * .27]));
      ctx.lineWidth = size * .21;
      ctx.strokeStyle = light < .31 ? '#ffd081a6' : '#ffe6a6ce';
      ctx.stroke();
    }
    ctx.restore();
  }

  function nori(ctx, corners, tone) {
    const [bottomLeft, topLeft, topRight, bottomRight] = corners;
    const locate = (u, v) => [
      mix(mix(topLeft[0], topRight[0], u), mix(bottomLeft[0], bottomRight[0], u), v),
      mix(mix(topLeft[1], topRight[1], u), mix(bottomLeft[1], bottomRight[1], u), v)
    ];
    const edge = [];
    for (let p = 0; p < 4; p++) {
      for (let i = 0; i < 30; i++) {
        const t = i / 30;
        const shake = between(-.026, .028) * Math.sin(t * Math.PI);
        edge.push(p === 0 ? locate(t, shake) : p === 1 ? locate(1 + shake, t) :
          p === 2 ? locate(1 - t, 1 + shake) : locate(shake, 1 - t));
      }
    }
    trace(ctx, edge, true);
    ctx.strokeStyle = '#10170f';
    ctx.lineWidth = 2.9;
    ctx.stroke();
    ctx.save();
    ctx.clip();
    ctx.fillStyle = linear(ctx, topLeft[0], topLeft[1], bottomRight[0], bottomRight[1], [
      [0, tone], [.42, '#303a24'], [.66, '#253021'], [1, '#141d15']
    ]);
    ctx.fillRect(-365, -243, 282, 232);
    for (let i = 0; i < 2050; i++) {
      const [x, y] = locate(random(), random());
      const size = between(.32, 2.85);
      oval(ctx, x, y, size, size * between(.21, .7),
        choose(['#a5a26648', '#6e7b405e', '#121a12c7', '#161d13ae', '#50623b9f', '#b4aa733e']),
        between(-1.2, .8));
    }
    for (let i = 0; i < 35; i++) {
      const u = random();
      const v = random();
      const [x, y] = locate(u, v);
      const [x1, y1] = locate(u + between(-.14, .12), v + between(.08, .32));
      curve(ctx, [x, y, mix(x, x1, .25) - 4, mix(y, y1, .25), mix(x, x1, .7) + 4, mix(y, y1, .7), x1, y1],
        choose(['#c0a97130', '#0a140eb4', '#77804a5a']), between(.35, 2.0));
    }
    ctx.restore();
    trace(ctx, edge.slice(0, 31));
    ctx.strokeStyle = '#a0955f64';
    ctx.lineWidth = .96;
    ctx.stroke();
  }

  function bokChoy(ctx, axis, spread, angle, palette) {
    ctx.save();
    ctx.translate(axis[0], axis[1]);
    ctx.rotate(angle);
    const length = axis[2];
    const drift = axis[3];

    function surface(t, side) {
      const blade = .15 + 1.07 * Math.pow(Math.sin(Math.PI * t), .9);
      const taper = t < .88 ? 1 : Math.pow((1 - t) / .12, .7);
      const bump = 1 + .085 * Math.sin(t * 35 + side * 1.3) + .047 * Math.sin(t * 68);
      const width = spread * blade * taper * (0.33 + .67 * smooth((t - .10) / .62));
      return [
        drift * t * t + (side + .18 * Math.sin(t * 4)) * width * bump,
        -t * length + side * (11 * Math.sin(t * 4.8) + 7 * t)
      ];
    }

    const outline = [];
    for (let i = 0; i <= 58; i++) outline.push(surface(i / 58, -1));
    for (let i = 58; i >= 0; i--) outline.push(surface(i / 58, 1));
    trace(ctx, outline, true);
    ctx.lineWidth = 3;
    ctx.strokeStyle = '#162619';
    ctx.stroke();
    ctx.save();
    ctx.clip();
    ctx.fillStyle = linear(ctx, 0, 0, drift, -length, [
      [0, '#6b7d39'], [.14, '#9eb270'], [.34, palette[0]], [.55, palette[1]],
      [.79, palette[2]], [1, palette[3]]
    ]);
    ctx.fillRect(-spread * 2 + Math.min(0, drift), -length - 18, 4 * spread + Math.abs(drift), length + 37);

    const right = [];
    for (let i = 0; i <= 55; i++) right.push(surface(i / 55, .08));
    for (let i = 55; i >= 0; i--) right.push(surface(i / 55, 1.16));
    trace(ctx, right, true);
    ctx.fillStyle = linear(ctx, -10, -length * .25, drift + spread, -length * .69, [
      [0, '#0c33220d'], [.31, '#0b322651'], [.65, '#092b249d'], [1, '#10191e61']
    ]);
    ctx.fill();

    for (let i = 0; i < 46; i++) {
      const t = between(.23, .97);
      const side = between(-1, 1);
      const points = [];
      for (let v = 0; v < 15; v++) {
        const amount = v / 14;
