const target = await fetch('http://localhost:9222/json/new?about:blank', { method: 'PUT' }).then(r => r.json());
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => {
  ws.addEventListener('open', resolve, { once: true });
  ws.addEventListener('error', reject, { once: true });
});
let id = 0;
const pending = new Map();
const errors = [];
const requests = [];
ws.addEventListener('message', e => {
  const message = JSON.parse(e.data);
  if (message.method === 'Runtime.exceptionThrown') errors.push(message.params);
  if (message.method === 'Network.requestWillBeSent') requests.push(message.params.request.url);
  const task = pending.get(message.id);
  if (!task) return;
  pending.delete(message.id);
  if (message.error) task.reject(new Error(JSON.stringify(message.error)));
  else task.resolve(message.result);
});
const call = (method, params = {}) => new Promise((resolve, reject) => {
  pending.set(++id, { resolve, reject });
  ws.send(JSON.stringify({ id, method, params }));
});
const evaluate = async expression => {
  const result = await call('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
  assert.equal(result.exceptionDetails, undefined);
  return result.result.value;
};
const metrics = (width, height, mobile = false, deviceScaleFactor = 1) =>
  call('Emulation.setDeviceMetricsOverride', { width, height, mobile, deviceScaleFactor });
const preference = value => call('Emulation.setEmulatedMedia', {
  features: [{ name: 'prefers-reduced-motion', value }]
});
const save = async name => {
  const { data } = await call('Page.captureScreenshot', { format: 'png' });
  await writeFile('<TMP>/ramen-' + name + '.png', Buffer.from(data, 'base64'));
};
const hash = (x, y, w, h) => evaluate(\`(() => {
  const pixels = document.querySelector('canvas').getContext('2d').getImageData(\${x},\${y},\${w},\${h}).data;
  let sum = 2166136261;
  for(let i = 0; i < pixels.length; i += 4) sum = Math.imul(sum ^ pixels[i] ^ pixels[i + 1] << 8, 16777619);
  return sum;
})()\`);
const checkDimensions = async (width, height) => {
  await sleep(120);
  const dimensions = await evaluate('(() => { const r = document.querySelector("canvas").getBoundingClientRect(); return [r.width, r.height, document.documentElement.scrollWidth, document.documentElement.scrollHeight]; })()');
  assert.deepEqual(dimensions, [width, height, width, height]);
};

try {
