  await metrics(1440, 900);
  await preference('reduce');
  await call('Page.navigate', { url: 'file:///app/index.html' });
  await sleep(900);
  await checkDimensions(1440, 900);
  await save('desktop-static');
  assert.equal(await evaluate('matchMedia("(prefers-reduced-motion: reduce)").matches'), true);
  const still = await hash(510, 80, 410, 435);
  await call('Input.dispatchMouseEvent', { type: 'mouseMoved', x: 1210, y: 287 });
  await sleep(450);
  assert.equal(await hash(510, 80, 410, 435), still, 'reduced motion keeps the scene still');

  await preference('no-preference');
  await sleep(260);
  const moving = await hash(510, 80, 410, 220);
  await sleep(400);
  assert.notEqual(await hash(510, 80, 410, 220), moving, 'steam changes over time');
  const testArea = [383, 254, 38, 26];
  const ambient = await hash(...testArea);
  await call('Input.dispatchMouseEvent', { type: 'mouseMoved', x: 630, y: 330 });
  await sleep(700);
  assert.notEqual(await hash(...testArea), ambient, 'pointer changes the ambient light');
  await save('desktop-moving');
  await preference('reduce');
  await sleep(220);
  assert.equal(await hash(510, 80, 410, 435), still, 'toggling reduced motion restores the still frame');

